use crate::voronoi::Voronoi;
use delaunator::{Point, triangulate};

mod misc;
#[cfg(test)]
mod tests;

use misc::NO_EDGE;
use misc::is_collinear;
use misc::jitter_unit;

/// Delaunay triangulation with D3-compatible API.
///
/// **Encapsulation.** The internal flat-array buffers are
/// `pub(crate)` rather than `pub` to plug a mutable-state leak — callers
/// previously could mutate `points`, `triangles`, etc. and silently
/// invalidate every cached structure. Read-only access is exposed via
/// the `points()`, `triangles()`, `halfedges()`, `hull()`, `inedges()`,
/// `hull_index()`, and `collinear()` accessors.
pub struct Delaunay {
    /// Flat coordinate array [x0, y0, x1, y1, ...].
    pub(crate) points: Vec<f64>,
    /// Triangle vertex indices.
    pub(crate) triangles: Vec<usize>,
    /// Half-edge index. `halfedges[e]` is the opposite half-edge, or `EMPTY`.
    pub(crate) halfedges: Vec<usize>,
    /// Convex hull point indices.
    pub(crate) hull: Vec<usize>,
    /// Incoming half-edge per point. `NO_EDGE` if not set.
    pub(crate) inedges: Vec<usize>,
    /// Maps hull point → position in hull array. `NO_EDGE` if not on hull.
    pub(crate) hull_index: Vec<usize>,
    /// Collinear point indices (sorted), or empty.
    pub(crate) collinear: Vec<usize>,
}

impl Delaunay {
    /// Create from (x, y) tuples.
    pub fn from_points(points: &[(f64, f64)]) -> Self {
        let flat: Vec<f64> = points.iter().flat_map(|(x, y)| [*x, *y]).collect();
        Self::new(flat)
    }

    /// Create from flat coordinates [x0, y0, x1, y1, ...].
    pub fn new(points: Vec<f64>) -> Self {
        let n = points.len() / 2;
        let del_points: Vec<Point> = (0..n)
            .map(|i| Point {
                x: points[i * 2],
                y: points[i * 2 + 1],
            })
            .collect();

        let tri = triangulate(&del_points);

        let mut inedges = vec![NO_EDGE; n];
        let mut hull_index = vec![NO_EDGE; n];
        let mut collinear_vec = Vec::new();

        let mut triangles = tri.triangles.clone();
        let mut halfedges = tri.halfedges.clone();
        let mut hull = tri.hull.clone();

        // Check for collinear points
        if hull.len() > 2 && is_collinear(&tri.triangles, &points) {
            let mut col: Vec<usize> = (0..n).collect();
            col.sort_by(|&i, &j| {
                points[2 * i]
                    .total_cmp(&points[2 * j])
                    .then(points[2 * i + 1].total_cmp(&points[2 * j + 1]))
            });
            collinear_vec = col;

            // Jitter and re-triangulate
            let e = collinear_vec[0];
            let f = collinear_vec[collinear_vec.len() - 1];
            let r = 1e-8
                * ((points[2 * f + 1] - points[2 * e + 1]).powi(2)
                    + (points[2 * f] - points[2 * e]).powi(2))
                .sqrt();

            let jittered: Vec<Point> = (0..n)
                .map(|i| {
                    let x = points[2 * i];
                    let y = points[2 * i + 1];
                    Point {
                        x: x + jitter_unit(i, x, y, 0x9e37_79b9_7f4a_7c15) * r,
                        y: y + jitter_unit(i, x, y, 0xbf58_476d_1ce4_e5b9) * r,
                    }
                })
                .collect();

            let tri2 = triangulate(&jittered);
            triangles = tri2.triangles;
            halfedges = tri2.halfedges;
            hull = tri2.hull;
        }

        // Compute inedges. If the input was collinear, the triangulation
        // above was built from jittered coordinates, but delaunator keeps
        // the same vertex indices, so these edge maps still refer to the
        // original points stored on `self`.
        for (e, _) in halfedges.iter().enumerate() {
            let p = triangles[if e % 3 == 2 { e - 2 } else { e + 1 }];
            if halfedges[e] == NO_EDGE || inedges[p] == NO_EDGE {
                inedges[p] = e;
            }
        }
        for (i, &h) in hull.iter().enumerate() {
            hull_index[h] = i;
        }

        // Degenerate: 1 or 2 distinct points
        if hull.len() <= 2 && !hull.is_empty() {
            triangles = vec![NO_EDGE; 3];
            halfedges = vec![NO_EDGE; 3];
            triangles[0] = hull[0];
            inedges[hull[0]] = 1;
            if hull.len() == 2 {
                inedges[hull[1]] = 0;
                triangles[1] = hull[1];
                triangles[2] = hull[1];
            }
        }

        Self {
            points,
            triangles,
            halfedges,
            hull,
            inedges,
            hull_index,
            collinear: collinear_vec,
        }
    }

    pub fn len(&self) -> usize {
        self.points.len() / 2
    }
    pub fn is_empty(&self) -> bool {
        self.points.is_empty()
    }
    pub fn point(&self, i: usize) -> (f64, f64) {
        (self.points[i * 2], self.points[i * 2 + 1])
    }

    /// Read-only access to the flat coordinate array `[x0, y0, x1, y1, ...]`.
    pub fn points(&self) -> &[f64] {
        &self.points
    }

    /// Read-only access to triangle vertex indices
    /// (`triangles.len() / 3` triangles, three vertex indices each).
    pub fn triangles(&self) -> &[usize] {
        &self.triangles
    }

    /// Read-only access to half-edge twin indices. `delaunator::EMPTY`
    /// marks hull edges.
    pub fn halfedges(&self) -> &[usize] {
        &self.halfedges
    }

    /// Convex hull point indices, in counter-clockwise order.
    pub fn hull(&self) -> &[usize] {
        &self.hull
    }

    /// Incoming half-edge per point. `delaunator::EMPTY` for unmapped points.
    pub fn inedges(&self) -> &[usize] {
        &self.inedges
    }

    /// Position of each point in the hull array. `delaunator::EMPTY` if
    /// the point is not on the hull.
    pub fn hull_index(&self) -> &[usize] {
        &self.hull_index
    }

    /// Sorted collinear point indices when the input is degenerate (all
    /// points on a line); empty otherwise.
    pub fn collinear(&self) -> &[usize] {
        &self.collinear
    }

    pub fn voronoi(&self, bounds: [f64; 4]) -> Voronoi<'_> {
        Voronoi::new(self, bounds)
    }

    pub fn neighbors(&self, i: usize) -> Vec<usize> {
        let mut result = Vec::new();
        if !self.collinear.is_empty() {
            if let Some(l) = self.collinear.iter().position(|&c| c == i) {
                if l > 0 {
                    result.push(self.collinear[l - 1]);
                }
                if l < self.collinear.len() - 1 {
                    result.push(self.collinear[l + 1]);
                }
            }
            return result;
        }
        let e0 = self.inedges[i];
        if e0 == NO_EDGE {
            return result;
        }
        let mut e = e0;
        loop {
            result.push(self.triangles[e]);
            e = if e % 3 == 2 { e - 2 } else { e + 1 };
            if self.triangles[e] != i {
                return result;
            }
            e = self.halfedges[e];
            if e == NO_EDGE {
                if self.hull_index[i] != NO_EDGE {
                    let p = self.hull[(self.hull_index[i] + 1) % self.hull.len()];
                    if !result.is_empty() && p != *result.last().unwrap() {
                        result.push(p);
                    }
                }
                return result;
            }
            if e == e0 {
                break;
            }
        }
        result
    }

    /// Find a point near `(x, y)` by greedy descent across the Delaunay graph.
    ///
    /// This matches d3-delaunay's local search: starting at `start`, each
    /// step moves to an adjacent vertex that is closer to the query. It is
    /// fast and exact for the common "near previous query" workflow, but
    /// queries outside the hull, or adversarial start vertices, are not a
    /// global nearest-neighbor guarantee.
    pub fn find(&self, x: f64, y: f64, start: usize) -> usize {
        if x.is_nan() || y.is_nan() {
            return NO_EDGE;
        }
        let mut i = start;
        let i0 = i;
        for _ in 0..self.len().max(1) {
            let c = self.step(i, x, y);
            if c == i || c == i0 {
                return c;
            }
            if c == NO_EDGE {
                return i;
            }
            i = c;
        }
        i
    }

    pub fn step(&self, i: usize, x: f64, y: f64) -> usize {
        if self.inedges[i] == NO_EDGE || self.points.is_empty() {
            return (i + 1) % self.len();
        }
        let mut c = i;
        let mut dc = (x - self.points[i * 2]).powi(2) + (y - self.points[i * 2 + 1]).powi(2);
        let e0 = self.inedges[i];
        let mut e = e0;
        loop {
            let t = self.triangles[e];
            let dt = (x - self.points[t * 2]).powi(2) + (y - self.points[t * 2 + 1]).powi(2);
            if dt < dc {
                dc = dt;
                c = t;
            }
            e = if e % 3 == 2 { e - 2 } else { e + 1 };
            if self.triangles[e] != i {
                break;
            }
            let he = self.halfedges[e];
            if he == NO_EDGE {
                if self.hull_index[i] != NO_EDGE {
                    let ep = self.hull[(self.hull_index[i] + 1) % self.hull.len()];
                    if ep != t {
                        let dep = (x - self.points[ep * 2]).powi(2)
                            + (y - self.points[ep * 2 + 1]).powi(2);
                        if dep < dc {
                            return ep;
                        }
                    }
                }
                break;
            }
            e = he;
            if e == e0 {
                break;
            }
        }
        c
    }

    pub fn circumcenter(&self, t: usize) -> (f64, f64) {
        let i = t * 3;
        let t1 = self.triangles[i] * 2;
        let t2 = self.triangles[i + 1] * 2;
        let t3 = self.triangles[i + 2] * 2;
        let (x1, y1) = (self.points[t1], self.points[t1 + 1]);
        let (x2, y2) = (self.points[t2], self.points[t2 + 1]);
        let (x3, y3) = (self.points[t3], self.points[t3 + 1]);
        // Translated coordinates with vertex 1 at the origin (same trick
        // `delaunator::circumradius2` uses for conditioning).
        let dx = x2 - x1;
        let dy = y2 - y1;
        let ex = x3 - x1;
        let ey = y3 - y1;
        let ab = (dx * ey - dy * ex) * 2.0;
        let bl = dx * dx + dy * dy;
        let cl = ex * ex + ey * ey;
        // Translation-invariant scale: sum of squared edge lengths from
        // vertex 1. The previous absolute-coordinate scale (max |x_i|,
        // |y_i|) inflated the threshold for valid triangles far from the
        // origin and substituted the centroid for non-degenerate
        // triangles.
        let scale_sq = bl + cl;
        let scale_sq = if scale_sq > 0.0 { scale_sq } else { 1.0 };
        // `ab` is twice the signed area, compare to a relative area
        // threshold (units of length²).
        let threshold = 1e-9 * scale_sq;
        if ab.abs() < threshold {
            ((x1 + x2 + x3) / 3.0, (y1 + y2 + y3) / 3.0)
        } else {
            let d = 1.0 / ab;
            (x1 + (ey * bl - dy * cl) * d, y1 + (dx * cl - ex * bl) * d)
        }
    }
}
